INSERT INTO question (title,content,tags,answer,submitNum,acceptedNum,judgeCase,judgeConfig,problemSpec,problemVersion,isPublished,thumbNum,favourNum,userId,isDelete,rowVersion,problemNo)
VALUES ('二分查找','## 题目描述

给定一个按严格升序排列的整数数组 `nums` 和目标值 `target`。如果目标值存在，返回它的下标；否则返回 `-1`。

要求算法的时间复杂度为 `O(log n)`。

## ACM 模式输入

第一行包含 `n` 和 `target`。第二行包含 `n` 个严格升序整数。

## ACM 模式输出

输出目标值下标，不存在则输出 `-1`。

## 核心代码模式

实现 `Solution.search(nums: int[], target: int) -> int`。

## 数据范围

- `1 ≤ n ≤ 10^5`
- `-10^9 ≤ nums[i], target ≤ 10^9`','["简单","数组","二分查找"]','维护闭区间 [left,right]，比较中点与 target 后舍弃不可能的一半。时间复杂度 O(log n)，空间复杂度 O(1)。',0,0,'[{"input":"6 9\\n-1 0 3 5 9 12\\n","output":"4\\n","isHidden":false},{"input":"6 2\\n-1 0 3 5 9 12\\n","output":"-1\\n","isHidden":false},{"input":"1 5\\n5\\n","output":"0\\n","isHidden":true},{"input":"5 -5\\n-9 -5 0 4 8\\n","output":"1\\n","isHidden":true},{"input":"7 20\\n1 4 7 10 13 16 19\\n","output":"-1\\n","isHidden":true}]','{"timeLimit":2000,"memoryLimit":262144,"outputLimitBytes":1048576}','{"mode":"function","className":"Solution","methodName":"search","parameters":[{"name":"nums","type":"int[]"},{"name":"target","type":"int"}],"returnType":"int","resultSource":"return","comparator":{"type":"EXACT"},"harnessVersion":1,"judgeCases":[{"input":"{\\"nums\\":[-1,0,3,5,9,12],\\"target\\":9}","output":"4","isHidden":false},{"input":"{\\"nums\\":[-1,0,3,5,9,12],\\"target\\":2}","output":"-1","isHidden":false},{"input":"{\\"nums\\":[5],\\"target\\":5}","output":"0","isHidden":true},{"input":"{\\"nums\\":[-9,-5,0,4,8],\\"target\\":-5}","output":"1","isHidden":true},{"input":"{\\"nums\\":[1,4,7,10,13,16,19],\\"target\\":20}","output":"-1","isHidden":true}]}',1,1,0,0,@admin_id,0,0,3);
