INSERT INTO question (title,content,tags,answer,submitNum,acceptedNum,judgeCase,judgeConfig,problemSpec,problemVersion,isPublished,thumbNum,favourNum,userId,isDelete,rowVersion,problemNo)
VALUES ('合并两个有序数组','## 题目描述

给定两个按非递减顺序排列的整数数组 `nums1` 和 `nums2`，将它们合并为一个新的非递减数组并返回。

## ACM 模式输入

第一行包含 `n` 和 `m`。第二、三行分别包含 `n` 和 `m` 个整数。

## ACM 模式输出

输出合并后的数组，元素以空格分隔。

## 核心代码模式

实现 `Solution.mergeSorted(nums1: int[], nums2: int[]) -> int[]`。

## 数据范围

- `1 ≤ n,m ≤ 10^5`
- `n+m ≤ 2×10^5`','["简单","数组","双指针"]','分别用指针扫描两个数组，每次取较小元素追加到结果，最后追加剩余部分。时间复杂度 O(n+m)，空间复杂度 O(n+m)。',0,0,'[{"input":"3 3\\n1 2 4\\n1 3 4\\n","output":"1 1 2 3 4 4\\n","isHidden":false},{"input":"2 3\\n-3 7\\n-2 0 8\\n","output":"-3 -2 0 7 8\\n","isHidden":false},{"input":"3 3\\n-3 -1 2\\n-2 2 5\\n","output":"-3 -2 -1 2 2 5\\n","isHidden":true},{"input":"1 1\\n0\\n0\\n","output":"0 0\\n","isHidden":true},{"input":"4 2\\n1 1 1 1\\n1 1\\n","output":"1 1 1 1 1 1\\n","isHidden":true}]','{"timeLimit":2000,"memoryLimit":262144,"outputLimitBytes":1048576}','{"mode":"function","className":"Solution","methodName":"mergeSorted","parameters":[{"name":"nums1","type":"int[]"},{"name":"nums2","type":"int[]"}],"returnType":"int[]","resultSource":"return","comparator":{"type":"EXACT"},"harnessVersion":1,"judgeCases":[{"input":"{\\"nums1\\":[1,2,4],\\"nums2\\":[1,3,4]}","output":"[1,1,2,3,4,4]","isHidden":false},{"input":"{\\"nums1\\":[-3,7],\\"nums2\\":[-2,0,8]}","output":"[-3,-2,0,7,8]","isHidden":false},{"input":"{\\"nums1\\":[],\\"nums2\\":[0]}","output":"[0]","isHidden":true},{"input":"{\\"nums1\\":[-3,-1,2],\\"nums2\\":[-2,2,5]}","output":"[-3,-2,-1,2,2,5]","isHidden":true},{"input":"{\\"nums1\\":[1,1,1,1],\\"nums2\\":[1,1]}","output":"[1,1,1,1,1,1]","isHidden":true}]}',1,1,0,0,@admin_id,0,0,5);
