INSERT INTO question (title,content,tags,answer,submitNum,acceptedNum,judgeCase,judgeConfig,problemSpec,problemVersion,isPublished,thumbNum,favourNum,userId,isDelete,rowVersion,problemNo)
VALUES ('爬楼梯','## 题目描述

你正在爬一段有 `n` 级台阶的楼梯。每次可以爬 `1` 级或 `2` 级，求到达楼顶共有多少种不同的方法。

## ACM 模式输入

输入一个整数 `n`。

## ACM 模式输出

输出不同方法数。

## 核心代码模式

实现 `Solution.climbStairs(n: int) -> int`。

## 数据范围

- `1 ≤ n ≤ 45`','["简单","动态规划","数学"]','到达第 n 级的最后一步来自 n-1 或 n-2，因此 f(n)=f(n-1)+f(n-2)。滚动保存两个状态即可。时间复杂度 O(n)，空间复杂度 O(1)。',0,0,'[{"input":"2\\n","output":"2\\n","isHidden":false},{"input":"5\\n","output":"8\\n","isHidden":false},{"input":"1\\n","output":"1\\n","isHidden":true},{"input":"10\\n","output":"89\\n","isHidden":true},{"input":"45\\n","output":"1836311903\\n","isHidden":true}]','{"timeLimit":2000,"memoryLimit":262144,"outputLimitBytes":1048576}','{"mode":"function","className":"Solution","methodName":"climbStairs","parameters":[{"name":"n","type":"int"}],"returnType":"int","resultSource":"return","comparator":{"type":"EXACT"},"harnessVersion":1,"judgeCases":[{"input":"{\\"n\\":2}","output":"2","isHidden":false},{"input":"{\\"n\\":5}","output":"8","isHidden":false},{"input":"{\\"n\\":1}","output":"1","isHidden":true},{"input":"{\\"n\\":10}","output":"89","isHidden":true},{"input":"{\\"n\\":45}","output":"1836311903","isHidden":true}]}',1,1,0,0,@admin_id,0,0,6);
SET @qid = LAST_INSERT_ID();
