-- 7. 零钱兑换
INSERT INTO question (title,content,tags,answer,submitNum,acceptedNum,judgeCase,judgeConfig,problemSpec,problemVersion,isPublished,thumbNum,favourNum,userId,isDelete,rowVersion,problemNo)
VALUES ('零钱兑换','## 题目描述

给定不同面额的硬币数组 `coins` 和总金额 `amount`。每种硬币可以使用任意次，返回凑成总金额所需的最少硬币数；无法凑成时返回 `-1`。

## ACM 模式输入

第一行包含硬币种数 `n` 和金额 `amount`。第二行包含 `n` 个硬币面额。

## ACM 模式输出

输出最少硬币数或 `-1`。

## 核心代码模式

实现 `Solution.coinChange(coins: int[], amount: int) -> int`。

## 数据范围

- `1 ≤ n ≤ 20`
- `1 ≤ coins[i] ≤ 10^4`
- `0 ≤ amount ≤ 10^4`','["中等","数组","动态规划"]','设 dp[x] 为组成金额 x 的最少硬币数。初始化 dp[0]=0，其余为不可达；对每个金额尝试所有不超过它的硬币。时间复杂度 O(n×amount)，空间复杂度 O(amount)。',0,0,'[{"input":"3 11\\n1 2 5\\n","output":"3\\n","isHidden":false},{"input":"1 3\\n2\\n","output":"-1\\n","isHidden":false},{"input":"1 0\\n1\\n","output":"0\\n","isHidden":true},{"input":"4 27\\n2 5 10 1\\n","output":"4\\n","isHidden":true},{"input":"4 6249\\n186 419 83 408\\n","output":"20\\n","isHidden":true}]','{"timeLimit":2000,"memoryLimit":262144,"outputLimitBytes":1048576}','{"mode":"function","className":"Solution","methodName":"coinChange","parameters":[{"name":"coins","type":"int[]"},{"name":"amount","type":"int"}],"returnType":"int","resultSource":"return","comparator":{"type":"EXACT"},"harnessVersion":1,"judgeCases":[{"input":"{\\"coins\\":[1,2,5],\\"amount\\":11}","output":"3","isHidden":false},{"input":"{\\"coins\\":[2],\\"amount\\":3}","output":"-1","isHidden":false},{"input":"{\\"coins\\":[1],\\"amount\\":0}","output":"0","isHidden":true},{"input":"{\\"coins\\":[2,5,10,1],\\"amount\\":27}","output":"4","isHidden":true},{"input":"{\\"coins\\":[186,419,83,408],\\"amount\\":6249}","output":"20","isHidden":true}]}',1,1,0,0,@admin_id,0,0,7);
SET @qid = LAST_INSERT_ID();
INSERT INTO question_version (questionId,version,title,content,tags,answer,judgeCase,judgeConfig,problemSpec,harnessVersion,publishedBy)
