INSERT INTO question (title,content,tags,answer,submitNum,acceptedNum,judgeCase,judgeConfig,problemSpec,problemVersion,isPublished,thumbNum,favourNum,userId,isDelete,rowVersion,problemNo)
VALUES ('最长公共子序列','## 题目描述

给定两个字符串 `text1` 和 `text2`，返回它们的最长公共子序列长度。子序列可以删除原字符串中的若干字符，但不能改变剩余字符的相对顺序。

## ACM 模式输入

输入两行，分别为 `text1` 和 `text2`。

## ACM 模式输出

输出最长公共子序列长度。

## 核心代码模式

实现 `Solution.longestCommonSubsequence(text1: string, text2: string) -> int`。

## 数据范围

- `1 ≤ |text1|,|text2| ≤ 1000`
- 字符串仅包含英文字母','["中等","字符串","动态规划"]','用 dp[i][j] 表示两个前缀的最长公共子序列长度。字符相等时取 dp[i-1][j-1]+1，否则取 dp[i-1][j] 与 dp[i][j-1] 的较大值。时间复杂度 O(nm)。',0,0,'[{"input":"abcde\\nace\\n","output":"3\\n","isHidden":false},{"input":"abc\\nabc\\n","output":"3\\n","isHidden":false},{"input":"abc\\ndef\\n","output":"0\\n","isHidden":true},{"input":"ezupkr\\nubmrapg\\n","output":"2\\n","isHidden":true},{"input":"AGGTAB\\nGXTXAYB\\n","output":"4\\n","isHidden":true}]','{"timeLimit":2000,"memoryLimit":262144,"outputLimitBytes":1048576}','{"mode":"function","className":"Solution","methodName":"longestCommonSubsequence","parameters":[{"name":"text1","type":"string"},{"name":"text2","type":"string"}],"returnType":"int","resultSource":"return","comparator":{"type":"EXACT"},"harnessVersion":1,"judgeCases":[{"input":"{\\"text1\\":\\"abcde\\",\\"text2\\":\\"ace\\"}","output":"3","isHidden":false},{"input":"{\\"text1\\":\\"abc\\",\\"text2\\":\\"abc\\"}","output":"3","isHidden":false},{"input":"{\\"text1\\":\\"abc\\",\\"text2\\":\\"def\\"}","output":"0","isHidden":true},{"input":"{\\"text1\\":\\"ezupkr\\",\\"text2\\":\\"ubmrapg\\"}","output":"2","isHidden":true},{"input":"{\\"text1\\":\\"AGGTAB\\",\\"text2\\":\\"GXTXAYB\\"}","output":"4","isHidden":true}]}',1,1,0,0,@admin_id,0,0,8);
SET @qid = LAST_INSERT_ID();
