-- 9. 岛屿数量
INSERT INTO question (title,content,tags,answer,submitNum,acceptedNum,judgeCase,judgeConfig,problemSpec,problemVersion,isPublished,thumbNum,favourNum,userId,isDelete,rowVersion,problemNo)
VALUES ('岛屿数量','## 题目描述

给定一个由字符 `0` 和 `1` 组成的二维网格。`1` 表示陆地，`0` 表示水域；上下左右相邻的陆地属于同一座岛屿。返回网格中的岛屿数量。

## ACM 模式输入

第一行包含行数 `n` 和列数 `m`，随后输入 `n` 行长度为 `m` 的字符串。

## ACM 模式输出

输出岛屿数量。

## 核心代码模式

实现 `Solution.numIslands(grid: string[]) -> int`。

## 数据范围

- `1 ≤ n,m ≤ 300`','["中等","矩阵","深度优先搜索","广度优先搜索"]','扫描网格，每遇到一块尚未访问的陆地就增加答案，并用 DFS 或 BFS 标记与它连通的全部陆地。时间复杂度 O(nm)，空间复杂度 O(nm)。',0,0,'[{"input":"4 5\\n11110\\n11010\\n11000\\n00000\\n","output":"1\\n","isHidden":false},{"input":"4 5\\n11000\\n11000\\n00100\\n00011\\n","output":"3\\n","isHidden":false},{"input":"1 1\\n1\\n","output":"1\\n","isHidden":true},{"input":"1 1\\n0\\n","output":"0\\n","isHidden":true},{"input":"3 3\\n101\\n010\\n101\\n","output":"5\\n","isHidden":true}]','{"timeLimit":2000,"memoryLimit":262144,"outputLimitBytes":1048576}','{"mode":"function","className":"Solution","methodName":"numIslands","parameters":[{"name":"grid","type":"string[]"}],"returnType":"int","resultSource":"return","comparator":{"type":"EXACT"},"harnessVersion":1,"judgeCases":[{"input":"{\\"grid\\":[\\"11110\\",\\"11010\\",\\"11000\\",\\"00000\\"]}","output":"1","isHidden":false},{"input":"{\\"grid\\":[\\"11000\\",\\"11000\\",\\"00100\\",\\"00011\\"]}","output":"3","isHidden":false},{"input":"{\\"grid\\":[\\"1\\"]}","output":"1","isHidden":true},{"input":"{\\"grid\\":[\\"0\\"]}","output":"0","isHidden":true},{"input":"{\\"grid\\":[\\"101\\",\\"010\\",\\"101\\"]}","output":"5","isHidden":true}]}',1,1,0,0,@admin_id,0,0,9);
SET @qid = LAST_INSERT_ID();
