-- 10. 合并区间
INSERT INTO question (title,content,tags,answer,submitNum,acceptedNum,judgeCase,judgeConfig,problemSpec,problemVersion,isPublished,thumbNum,favourNum,userId,isDelete,rowVersion,problemNo)
VALUES ('合并区间','## 题目描述

给定若干闭区间 `intervals[i] = [start, end]`，合并所有重叠或相接的区间，返回按起点升序排列且互不重叠的区间。

## ACM 模式输入

第一行是区间数量 `n`，随后 `n` 行各包含两个整数 `start` 和 `end`。

## ACM 模式输出

第一行输出合并后的区间数量，随后每行输出一个区间。

## 核心代码模式

实现 `Solution.merge(intervals: int[][]) -> int[][]`。

## 数据范围

- `1 ≤ n ≤ 10^5`
- `0 ≤ start ≤ end ≤ 10^9`','["中等","数组","排序"]','按区间起点排序。依次扫描：若当前区间起点不大于结果末尾区间终点，则扩展终点；否则追加新区间。时间复杂度 O(n log n)。',0,0,'[{"input":"4\\n1 3\\n2 6\\n8 10\\n15 18\\n","output":"3\\n1 6\\n8 10\\n15 18\\n","isHidden":false},{"input":"2\\n1 4\\n4 5\\n","output":"1\\n1 5\\n","isHidden":false},{"input":"3\\n1 4\\n0 2\\n3 5\\n","output":"1\\n0 5\\n","isHidden":true},{"input":"1\\n7 9\\n","output":"1\\n7 9\\n","isHidden":true},{"input":"5\\n1 2\\n3 4\\n5 8\\n6 7\\n8 10\\n","output":"3\\n1 2\\n3 4\\n5 10\\n","isHidden":true}]','{"timeLimit":2000,"memoryLimit":262144,"outputLimitBytes":1048576}','{"mode":"function","className":"Solution","methodName":"merge","parameters":[{"name":"intervals","type":"int[][]"}],"returnType":"int[][]","resultSource":"return","comparator":{"type":"EXACT"},"harnessVersion":1,"judgeCases":[{"input":"{\\"intervals\\":[[1,3],[2,6],[8,10],[15,18]]}","output":"[[1,6],[8,10],[15,18]]","isHidden":false},{"input":"{\\"intervals\\":[[1,4],[4,5]]}","output":"[[1,5]]","isHidden":false},{"input":"{\\"intervals\\":[[1,4],[0,2],[3,5]]}","output":"[[0,5]]","isHidden":true},{"input":"{\\"intervals\\":[[7,9]]}","output":"[[7,9]]","isHidden":true},{"input":"{\\"intervals\\":[[1,2],[3,4],[5,8],[6,7],[8,10]]}","output":"[[1,2],[3,4],[5,10]]","isHidden":true}]}',1,1,0,0,@admin_id,0,0,10);
