-- 11. 最小路径和
INSERT INTO question (title,content,tags,answer,submitNum,acceptedNum,judgeCase,judgeConfig,problemSpec,problemVersion,isPublished,thumbNum,favourNum,userId,isDelete,rowVersion,problemNo)
VALUES ('最小路径和','## 题目描述

给定一个包含非负整数的 `m × n` 网格，从左上角出发，每次只能向右或向下移动，求到达右下角路径上的最小数字总和。

## ACM 模式输入

第一行包含 `m` 和 `n`，随后输入 `m` 行、每行 `n` 个整数。

## ACM 模式输出

输出最小路径和。

## 核心代码模式

实现 `Solution.minPathSum(grid: int[][]) -> int`。

## 数据范围

- `1 ≤ m,n ≤ 200`
- `0 ≤ grid[i][j] ≤ 100`','["中等","矩阵","动态规划"]','令 dp[i][j] 为到达单元格 (i,j) 的最小路径和，它等于当前值加上上方和左方状态中的较小值。可用一维数组压缩空间。时间复杂度 O(mn)。',0,0,'[{"input":"3 3\\n1 3 1\\n1 5 1\\n4 2 1\\n","output":"7\\n","isHidden":false},{"input":"2 3\\n1 2 3\\n4 5 6\\n","output":"12\\n","isHidden":false},{"input":"1 1\\n5\\n","output":"5\\n","isHidden":true},{"input":"2 2\\n0 0\\n0 0\\n","output":"0\\n","isHidden":true},{"input":"3 4\\n1 9 1 1\\n1 9 1 9\\n1 1 1 1\\n","output":"6\\n","isHidden":true}]','{"timeLimit":2000,"memoryLimit":262144,"outputLimitBytes":1048576}','{"mode":"function","className":"Solution","methodName":"minPathSum","parameters":[{"name":"grid","type":"int[][]"}],"returnType":"int","resultSource":"return","comparator":{"type":"EXACT"},"harnessVersion":1,"judgeCases":[{"input":"{\\"grid\\":[[1,3,1],[1,5,1],[4,2,1]]}","output":"7","isHidden":false},{"input":"{\\"grid\\":[[1,2,3],[4,5,6]]}","output":"12","isHidden":false},{"input":"{\\"grid\\":[[5]]}","output":"5","isHidden":true},{"input":"{\\"grid\\":[[0,0],[0,0]]}","output":"0","isHidden":true},{"input":"{\\"grid\\":[[1,9,1,1],[1,9,1,9],[1,1,1,1]]}","output":"6","isHidden":true}]}',1,1,0,0,@admin_id,0,0,11);
SET @qid = LAST_INSERT_ID();
