-- 12. 最长递增子序列
INSERT INTO question (title,content,tags,answer,submitNum,acceptedNum,judgeCase,judgeConfig,problemSpec,problemVersion,isPublished,thumbNum,favourNum,userId,isDelete,rowVersion,problemNo)
VALUES ('最长递增子序列','## 题目描述

给定一个整数数组 `nums`，返回其中最长严格递增子序列的长度。子序列不要求连续，但必须保持原数组中的相对顺序。

## ACM 模式输入

第一行是数组长度 `n`，第二行是 `n` 个整数。

## ACM 模式输出

输出最长严格递增子序列长度。

## 核心代码模式

实现 `Solution.lengthOfLIS(nums: int[]) -> int`。

## 数据范围

- `1 ≤ n ≤ 2500`
- `-10^4 ≤ nums[i] ≤ 10^4`','["中等","数组","动态规划","二分查找"]','基础解法用 dp[i] 表示以 nums[i] 结尾的最长递增子序列，复杂度 O(n²)。也可维护每个长度对应的最小末尾元素并二分替换，做到 O(n log n)。',0,0,'[{"input":"8\\n10 9 2 5 3 7 101 18\\n","output":"4\\n","isHidden":false},{"input":"6\\n0 1 0 3 2 3\\n","output":"4\\n","isHidden":false},{"input":"7\\n7 7 7 7 7 7 7\\n","output":"1\\n","isHidden":true},{"input":"8\\n-1 3 4 5 2 2 2 2\\n","output":"4\\n","isHidden":true},{"input":"5\\n5 4 3 2 1\\n","output":"1\\n","isHidden":true},{"input":"1\\n7\\n","output":"1\\n","isHidden":true}]','{"timeLimit":2000,"memoryLimit":262144,"outputLimitBytes":1048576}','{"mode":"function","className":"Solution","methodName":"lengthOfLIS","parameters":[{"name":"nums","type":"int[]"}],"returnType":"int","resultSource":"return","comparator":{"type":"EXACT"},"harnessVersion":1,"judgeCases":[{"input":"{\\"nums\\":[10,9,2,5,3,7,101,18]}","output":"4","isHidden":false},{"input":"{\\"nums\\":[0,1,0,3,2,3]}","output":"4","isHidden":false},{"input":"{\\"nums\\":[7,7,7,7,7,7,7]}","output":"1","isHidden":true},{"input":"{\\"nums\\":[-1,3,4,5,2,2,2,2]}","output":"4","isHidden":true},{"input":"{\\"nums\\":[5,4,3,2,1]}","output":"1","isHidden":true},{"input":"{\\"nums\\":[7]}","output":"1","isHidden":true}]}',1,1,0,0,@admin_id,0,0,12);
